      var spec = o.spec ? '<div class="rb-spec">' + ink('По специальному назначению' + (c.form === '107' && o.long && o.per ? ', ' + esc(o.per) : '')) + '<span class="rb-sig">' + ink('<i>Петрова</i>') + '</span>' + forRx + '</div>' : '';
      var h;
